var e=JSON.parse(`{"wrist-circles":{"name":"Círculos de muñeca","description":"De pie, con los codos suaves y los antebrazos frente a ti. Dibuja círculos lentos con ambas muñecas, cuatro tiempos hacia un lado y cuatro hacia el otro, manteniendo los dedos relajados.","goodFor":"Calienta las muñecas y los antebrazos, que hacen la mayor parte del trabajo con cualquier implemento.","alignmentCues":["Los codos se quedan quietos; solo se mueven las muñecas.","Mantén los círculos amplios y fluidos."],"commonMistakes":["Apurar los círculos hasta que se conviertan en latigazos."]},"arm-circles":{"name":"Círculos de brazos","description":"Pies al ancho de las caderas, brazos largos. Balancea ambos brazos en círculos amplios hacia adelante durante cuatro tiempos, luego hacia atrás otros cuatro, dejando que los omóplatos se deslicen.","goodFor":"Abre los hombros para los giros de staff y el trabajo de hoop por encima de la cabeza.","alignmentCues":["Las costillas se mantienen abajo mientras los brazos pasan por encima de la cabeza.","Exhala en el descenso."]},"shoulder-rolls":{"name":"Rodamientos de hombros","description":"Brazos relajados a los lados. Sube los hombros hacia las orejas, ródalos hacia atrás y abajo, y repite en un bucle lento.","goodFor":"Libera la tensión que vuelve los lanzamientos rígidos y cortos."},"neck-rolls":{"name":"Medios círculos de cuello","description":"Baja el mentón hacia el pecho y deslízalo lentamente de hombro a hombro en medio círculo. Evita que la cabeza se incline hacia atrás.","goodFor":"Alivia el cuello antes de mirar hacia arriba los lanzamientos durante largos periodos.","avoidIf":["Lesión de cuello o mareo al mover la cabeza."]},"hip-circles":{"name":"Círculos de cadera","description":"Manos en las caderas, rodillas suaves. Circula las caderas lentamente hacia un lado durante dos compases y hacia el otro durante dos, manteniendo la cabeza nivelada.","goodFor":"Prepara las caderas para el waist hooping y el cuerpo para el flow."},"torso-twists":{"name":"Torsiones de torso","description":"Pies anchos, brazos sueltos. Gira las costillas a izquierda y derecha y deja que los brazos se balanceen y se envuelvan alrededor de ti como mangas vacías.","goodFor":"Despierta la rotación para los weaves de staff y los pases de hoop."},"knee-bounce":{"name":"Rebote de rodillas","description":"De pie con los pies bajo las caderas y rebota suavemente con las rodillas en cada beat, con los brazos balanceándose sueltos. Encuentra la música en tus piernas.","goodFor":"Pone el beat en tu cuerpo antes de que tomes un implemento."},"one-ball-toss":{"name":"Lanzamiento de una pelota","description":"Sostén una pelota en tu mano derecha a la altura de la cintura. Recógela hacia adentro, luego lánzala en un arco que alcance su punto más alto justo por encima del nivel de los ojos y caiga en la mano izquierda. Lánzala de vuelta de la misma manera. Mantén la vista en la cima del arco, no en tus manos.","goodFor":"Construye el arco del que está hecho cada patrón de malabares.","alignmentCues":["Codos pegados a los costados, antebrazos nivelados.","La cima tiene la misma altura en cada lanzamiento.","Atrapa a la altura de la cintura y deja que la mano ceda un poco."],"commonMistakes":["Lanzar hacia adelante y tener que dar un paso tras la pelota.","Mirar las manos en vez de la cima."]},"two-ball-exchange":{"name":"Intercambio de dos pelotas","description":"Una pelota en cada mano. Lanza la pelota derecha en su arco; cuando llegue a la cima, lanza la pelota izquierda por debajo de ella, por dentro. Atrapa ambas y pausa. Luego empieza con la mano izquierda.","goodFor":"Enseña el intercambio: el segundo lanzamiento sale cuando el primero llega a la cima.","alignmentCues":["Segundo lanzamiento en la cima, nunca antes.","Lanza la segunda pelota por dentro de la primera."],"commonMistakes":["Pasar la segunda pelota al otro lado en lugar de lanzarla.","Lanzar ambas a la vez."]},"cascade":{"name":"Cascada de tres pelotas","description":"Dos pelotas en la mano derecha, una en la izquierda. Lanza desde la derecha; cuando llegue al punto más alto, lanza desde la izquierda; cuando esa llegue al punto más alto, lanza desde la derecha otra vez. Cada lanzamiento va al ritmo, cruzando a la otra mano en un arco en forma de 8.","goodFor":"El patrón fundamental del malabarismo.","modifications":["Practica el flash: tres lanzamientos, tres recepciones, para."],"deepen":["Haz malabares a un tempo más rápido con puntos más bajos.","Cuenta 20 recepciones sin que se caiga ninguna."],"alignmentCues":["Lanza desde dentro, recibe por fuera.","Puntos altos nivelados, a la altura de los ojos.","Ponte contra una pared si sigues avanzando."],"commonMistakes":["Lanzar hacia adelante y perseguir el patrón.","Apurarse apenas un lanzamiento sale mal."]},"reverse-cascade":{"name":"Cascada inversa","description":"La cascada al revés: cada pelota se lanza desde fuera, por encima del patrón, y cae por el centro hacia la otra mano.","goodFor":"Entrena lanzamientos desde fuera y abre trucos como el Mills Mess.","alignmentCues":["Los lanzamientos pasan por encima de la pelota que llega.","Recibe en el centro."]},"siteswap-423":{"name":"423","description":"Un patrón de tres pelotas: un autolanzamiento alto (4), una pelota sostenida (2), luego un lanzamiento de cascada (3). El 4 sube por el mismo lado; el 2 simplemente se sostiene durante un tiempo.","goodFor":"Tu primer truco de siteswap: enseña lanzamientos altos y sostenes."},"siteswap-441":{"name":"441","description":"Dos lanzamientos altos que se quedan de su propio lado (4, 4) seguidos de un zip rápido cruzado (1) de mano a mano.","goodFor":"Construye el timing entre lanzamientos altos y pases rápidos."},"two-in-one":{"name":"Dos en una mano","description":"Haz malabares con dos pelotas en una mano en columnas lado a lado o pequeños círculos hacia afuera, un lanzamiento cada dos tiempos. Practica cada mano.","goodFor":"El bloque de construcción del malabarismo con cuatro pelotas."},"siteswap-531":{"name":"531","description":"Un lanzamiento cruzado muy alto (5), un lanzamiento de cascada (3) y un zip rápido (1). El 5 sube mientras las otras dos pelotas siguen trabajando por debajo.","goodFor":"Control de altura y un truco de tres pelotas para lucir."},"shower":{"name":"Ducha de tres pelotas","description":"Las pelotas viajan en círculo: la mano derecha lanza cada pelota alto hacia la izquierda, y la mano izquierda pasa cada una directo de vuelta a la derecha.","goodFor":"Patrón circular clásico; entrena pases rápidos de mano a mano."},"mills-mess":{"name":"Mills Mess","description":"Una cascada de tres pelotas donde los brazos se cruzan y descruzan continuamente, así que cada lanzamiento sale del lado opuesto del cuerpo. Las trayectorias de las pelotas trazan un patrón entrelazado.","goodFor":"Un favorito del público que agudiza la coordinación."},"four-ball-fountain":{"name":"Fuente de cuatro pelotas","description":"Cada mano hace malabares con dos pelotas en su propia columna, las manos alternan los lanzamientos para que el patrón nunca se cruce.","goodFor":"Tu primer patrón de cuatro pelotas."},"sync-fountain":{"name":"Fuente sincrónica","description":"Cuatro pelotas con ambas manos lanzando exactamente en el mismo momento, cada una hacia su propio lado.","goodFor":"Construye simetría y lleva a trucos sincrónicos."},"five-ball-cascade":{"name":"Cascada de cinco pelotas","description":"La cascade con cinco pelotas: lanzamientos altos y rápidos en un patrón cruzado elevado. Cuenta con meses de práctica.","goodFor":"Un hito para malabaristas dedicados."},"staff-wheel-spin":{"name":"Giro de rueda a dos manos","description":"Sostén el staff por el centro con ambas manos, palmas hacia abajo, a la altura del pecho. Gíralo a tu lado como una rueda pasando la rotación entre las manos, manteniéndolo junto a tu cuerpo.","goodFor":"El primer giro de staff; desarrolla el agarre y la rotación de muñeca.","alignmentCues":["El staff se mantiene paralelo a tu cuerpo, sin inclinarse.","Agarre suave: deja que ruede entre los dedos."],"props":["bastón"],"commonMistakes":["Apretar tanto que el giro se detiene.","Inclinar el plano hacia adelante."]},"staff-front-spin":{"name":"Molino frontal","description":"Gira el staff frente a ti como una hélice, en el plano de pared, pasándolo suavemente de mano en mano alrededor de su centro.","goodFor":"Añade el plano de pared y el paso mano sobre mano.","props":["bastón"]},"staff-figure-8":{"name":"Tejido en ocho","description":"Gira el staff en el plano de rueda a tu lado derecho, luego crúzalo hacia tu lado izquierdo y gira allí, trazando un ocho frente a ti.","goodFor":"Conecta ambos lados del cuerpo; la base del flow con staff.","alignmentCues":["Cambia de lado cuando las puntas pasen por el suelo.","Rota un poco el torso con cada lado."],"props":["bastón"]},"staff-pass-through":{"name":"Paso a través","description":"Gira en el plano de pared pero suelta en cada media vuelta: una mano libera el staff y la otra lo atrapa por el centro, de modo que el staff pasa entre tus manos.","goodFor":"Enseña el timing de soltar y atrapar.","props":["bastón"]},"staff-one-hand-spin":{"name":"Giro a una mano","description":"Gira el staff frente a ti con una mano, haciéndolo rodar sobre el dorso de la mano y entre los dedos. Practica con ambas manos.","goodFor":"Fuerza de dedos y muñeca; libera la otra mano para trucos.","props":["bastón"]},"staff-helicopter":{"name":"Helicóptero sobre la cabeza","description":"Levanta el staff sobre tu cabeza y gíralo plano en el plano del suelo con una mano, como las aspas de un helicóptero.","goodFor":"Introduce el plano del suelo.","props":["bastón"]},"staff-butterfly":{"name":"Mariposa","description":"Gira frente a ti, luego pliega el staff detrás de tu hombro y sácalo de nuevo, alternando frente y atrás en cada lado como alas.","goodFor":"Movilidad de hombros y una transición fluida de frente a atrás.","props":["bastón"]},"staff-behind-back-pass":{"name":"Pase por detrás de la espalda","description":"Pasa el staff girando de una mano a la otra por detrás de tu espalda en la parte baja del giro, luego tráelo de vuelta al frente.","goodFor":"Enrolles corporales y pases de exhibición.","props":["bastón"]},"staff-isolation":{"name":"Aislamiento con staff","description":"Sostén el staff cerca de un extremo y gira la mano alrededor del centro del staff, de modo que el centro parezca quedarse fijo en el aire mientras el staff gira a su alrededor.","goodFor":"Trabajo de ilusión y trayectorias de mano precisas.","props":["bastón"]},"staff-antispin-flower":{"name":"Antispin de cuatro pétalos","description":"Gira la mano en una dirección mientras el staff gira en la otra tres veces más rápido, de modo que el staff dibuja una flor de cuatro pétalos.","goodFor":"La flor VTG característica; control profundo del timing.","props":["bastón"]},"staff-neck-roll":{"name":"Rodada por el cuello","description":"Suelta el staff sobre la parte posterior de los hombros y déjalo rodar por el cuello hasta la otra mano. Empieza despacio con un staff acolchado.","goodFor":"Contact staff: el staff se mueve sobre el cuerpo sin las manos.","avoidIf":["Dolor de cuello."],"props":["bastón"]},"hoop-waist":{"name":"Hula hoop en la cintura","description":"Párate con un pie ligeramente delante del otro. Sostén el hoop contra la parte baja de la espalda, lánzalo alrededor de la cintura y empuja el vientre hacia delante y hacia atrás (no en círculos) cada vez que el hoop pase por delante.","goodFor":"La primera habilidad con hoop; construye el ritmo del core.","modifications":["Usa un hoop más grande y pesado: gira más despacio."],"alignmentCues":["Balancea de delante hacia atrás, no en círculos.","Empuja el hoop cuando pase por tu vientre."],"props":["hoop"],"commonMistakes":["Mover las caderas en círculos como un hula dancer.","Un hoop demasiado pequeño o ligero."]},"hoop-hand-spin":{"name":"Giro con la mano","description":"Sostén el hoop delante de ti con la mano dentro de él, pulgar hacia arriba. Empújalo para que gire alrededor de la membrana de tu mano, manteniendo el hoop plano delante de ti.","goodFor":"Base del hoop off-body.","props":["hoop"]},"hoop-chest":{"name":"Hula hoop en el pecho","description":"Levanta los brazos por encima de la cabeza y haz hoop alrededor del pecho, meciendo la caja torácica de delante hacia atrás mientras mantienes las caderas quietas.","goodFor":"Aísla la caja torácica y desarrolla el control de la parte superior del cuerpo.","props":["hoop"]},"hoop-lasso":{"name":"Lazo","description":"Sostén el hoop por encima de la cabeza y gíralo plano sobre ella como un lazo, con el hoop girando alrededor de tu mano.","goodFor":"Control del plano del suelo por encima de la cabeza.","props":["hoop"]},"hoop-wedgie":{"name":"Wedgie","description":"Gira el hoop en el plano de pared y atrápalo en el hueco entre el pulgar y los dedos, dejando que ruede y se balancee ahí antes de seguir girando.","goodFor":"Control del agarre y una transición fluida.","props":["hoop"]},"hoop-knees":{"name":"Hula hoop en las rodillas","description":"Con los pies juntos, mantén el hoop girando alrededor de las rodillas empujándolas hacia delante y hacia atrás.","goodFor":"Práctica de hula hoop de tren inferior y escalator.","props":["hoop"]},"hoop-pass":{"name":"Pase mano a mano","description":"Gira el hoop frente a ti y pásalo de una mano a la otra en cada revolución, manteniendo el plano estable.","goodFor":"Enlaza trucos fuera del cuerpo por ambos lados.","props":["hoop"]},"hoop-isolation":{"name":"Isolation con hoop","description":"Mueve la mano alrededor del hoop para que su centro quede fijo en el aire frente a ti mientras el hoop gira sobre ese punto.","goodFor":"La ilusión clásica del hoop.","props":["hoop"]},"hoop-escalator":{"name":"Escalator","description":"Mantén el hoop girando mientras lo bajas de la cintura a las rodillas y lo subes de nuevo al pecho, una zona del cuerpo por compás.","goodFor":"Une todas las zonas del body hooping en un solo flow.","props":["hoop"]},"hoop-neck":{"name":"Hoop en el cuello","description":"Inclina ligeramente la cabeza y deja que un hoop ligero gire alrededor del cuello, guiado por pequeños impulsos de cabeza y hombros.","goodFor":"Un movimiento de show que entrena impulsos pequeños y precisos.","avoidIf":["Dolor de cuello."],"props":["hoop"]},"shake-out":{"name":"Sacudida","description":"Suelta los props y sacude manos y antebrazos. Deja caer los hombros.","goodFor":"Un reinicio corto entre rondas intensas."},"breathe":{"name":"Respira y reinicia","description":"Quédate quieto, cierra o suaviza los ojos y respira lento por la nariz y suelta por la boca.","goodFor":"Baja el ritmo cardíaco y despeja la frustración después de los drops.","breathCue":"Inhala en cuatro, exhala en cuatro."}}`),t={"warmup-mobility":{name:`Calentamiento de flow`,description:`Muñecas, hombros, columna y caderas sueltos a un ritmo constante. Úsalo antes de cualquier sesión con props.`,focus:`Calentamiento · movilidad`},"first-throws":{name:`Primeros lanzamientos`,description:`Una pelota en arco de mano a mano a la altura de los ojos, luego el intercambio de dos pelotas del que nace todo patrón.`,focus:`Malabares · fundamentos`},"cascade-builder":{name:`Constructor de cascade`,description:`Intercambios de dos pelotas seguidos hasta que se sume la tercera: rondas cortas de cascade, reinicio, otra vez.`,focus:`Malabares · fundamentos`},"juggling-tempo-ladder":{name:`Escalera de tempo en cascade`,description:`El cascade a tres tempos, unos beats más rápido en cada peldaño. Lanzamientos más bajos en los peldaños rápidos.`,focus:`Malabares · tempo`},"siteswap-sampler":{name:`Muestrario de siteswap`,description:`Cascade hacia 423, 441 y 531, con el reverse cascade y el shower como limpiadores de paladar. Todo patrón empieza y termina en el cascade.`,focus:`Malabares · patrones`},"four-ball-session":{name:`Sesión de cuatro pelotas`,description:`Dos en una mano por cada lado, la fuente de cuatro pelotas, luego la fuente sincrónica.`,focus:`Malabares · números`},"juggling-combo-flow":{name:`Flow de combos de malabares`,description:`Un set largo y fluido: cascade, reverse cascade, Mills mess y los siteswaps enlazados en una sola pieza musical.`,focus:`Malabares · combos`},"staff-first-spins":{name:`Primeros giros de staff`,description:`El wheel spin al lado del cuerpo, luego el front spin. Giros lentos y uniformes, uno por beat.`,focus:`Staff · fundamentos`},"staff-foundations":{name:`Fundamentos de staff`,description:`Wheel spin, front spin, figura 8 y el pass-through de mano a mano enlazados al beat.`,focus:`Staff · fundamentos`},"staff-flow-weave":{name:`Flow weave de staff`,description:`Figura 8 hacia butterfly, giros a una mano y el helicopter, unidos para que el staff nunca se detenga.`,focus:`Bastón · flow`},"staff-isolation-lab":{name:`Laboratorio de isolations de staff`,description:`Isolations y la antispin flower a un tempo más lento, con passes por detrás de la espalda entre medio.`,focus:`Staff · técnico`},"staff-advanced-flow":{name:`Flow avanzado de staff`,description:`El vocabulario completo en una sola pieza larga: weaves, wraps, isolations y el neck roll.`,focus:`Bastón · flow`},"hoop-first-spins":{name:`Primeros giros de hoop`,description:`Hooping en cintura con un empuje adelante-atrás, luego girar el hoop alrededor de una mano.`,focus:`Hoop · fundamentos`},"hoop-body-flow":{name:`Flow on-body de hoop`,description:`Mover el hoop subiendo al pecho y bajando a las rodillas y de vuelta a la cintura, sin parar.`,focus:`Hoop · en el cuerpo`},"hoop-off-body":{name:`Hoop off-body`,description:`Giros de mano, lasso, wedgies y passes, terminando con isolations que mantienen el hoop quieto en el espacio.`,focus:`Hoop · fuera del cuerpo`},"hoop-full-flow":{name:`Flow completo de hoop`,description:`On-body y off-body juntos: escalators, neck hooping y los trucos off-body en un solo flow largo.`,focus:`Hoop · flow`},"daily-mixed-flow":{name:`Flow mixto diario`,description:`Un poco de cada arte: cascade, giros de staff y hooping, con un movimiento de movilidad entre props.`,focus:`Mixto · práctica`}},n=JSON.parse(`{"start-here":{"title":"Empieza aquí: tu primera semana de flow","summary":"Elige un prop, practica diez minutos al día al beat, y deja que el árbol de desbloqueo te diga qué sigue.","imageAlt":"Figura 3D lanzando una sola pelota de malabares de mano a mano","body":["Las artes de flujo parecen magia desde fuera: pelotas suspendidas en el aire, un bastón que se convierte en un borrón, un aro orbitando a una bailarina que apenas parece moverse. Desde dentro son una pila de habilidades muy pequeñas, cada una aprendible en una tarde, superpuestas hasta que la pila parece no costar esfuerzo. Tu primera semana trata de la base de esa pila.","Elige un implemento para empezar. El malabarismo enseña timing y coordinación mano-ojo; el bastón enseña planos y cambios de mano suaves; el aro enseña ritmo con todo el cuerpo. Puedes aprender los tres, pero uno a la vez mantiene tu atención donde está el progreso. El árbol de Recompensas muestra cada movimiento de cada arte, desde el primer lanzamiento o giro hasta patrones avanzados, y abre los siguientes cuando dominas aquello sobre lo que se construyen.","Practica poco y a menudo. Diez minutos enfocados al día superan a una hora el domingo, porque la coordinación se consolida entre sesiones, sobre todo durante el sueño. Una rutina corta de la página de Rutinas, un calentamiento y unos cuantos pasos contados de tu movimiento actual es una práctica completa.","Practica al ritmo desde el primer día. Cada movimiento en SynthFlow se cuenta en compases a un tempo, con música o percusión generada que coincide. El ritmo te da algo a lo que aferrarte cuando el implemento no coopera, y hace que el progreso sea medible: una ronda limpia a 90 BPM esta semana, 100 la próxima.","Espera caídas. Todo el mundo deja caer, incluidos los profesionales en ensayo. Una caída te dice qué lanzamiento o recepción necesita atención; no dice nada sobre el talento. Recoge el implemento, espera al siguiente tiempo fuerte y vuelve a intentarlo. Al final de la semana tendrás un movimiento que puedes hacer sin pensar, y ese es el momento en que empieza el flow."]},"counting-and-the-beat":{"title":"Cuentas, compases y el ritmo","summary":"Por qué cada movimiento se cuenta en compases a un tempo, y cómo encajar tus lanzamientos y giros en la música.","imageAlt":"Figura 3D haciendo malabares con una cascade de tres pelotas con arcos dibujados sobre las manos","body":["La música está hecha de pulsos agrupados en compases, normalmente cuatro pulsos por compás. Los movimientos de flujo están hechos de ciclos: un lanzamiento de cada mano, media vuelta del bastón, una órbita del aro. Cuando un ciclo cae en el pulso, el movimiento y la música se vuelven una sola cosa. Por eso SynthFlow mide cada paso de rutina en compases en lugar de segundos, y por eso cada movimiento indica cuántos pulsos dura un ciclo.","En una cascade de tres pelotas cada lanzamiento cae en un pulso, alternando derecha e izquierda. En un front spin de bastón, media vuelta suele durar un pulso. El hooping en la cintura suele ser una órbita por pulso a un tempo relajado. Las cuentas del reproductor nombran lo que ocurre en cada pulso, y la figura 3D se mueve exactamente en el mismo reloj que el audio, para que puedas copiarla a tiempo.","El tempo se mide en pulsos por minuto (BPM). Cada movimiento tiene un rango cómodo: lo bastante lento para mantenerse limpio, lo bastante rápido para que el implemento conserve su inercia. Por debajo del rango los implementos que giran se estancan y los lanzamientos suben tanto que se desvían; por encima empiezas a apresurarte y a dejar caer. El editor te avisa cuando un paso queda fuera del rango de su movimiento.","Empieza cada paso en el tiempo fuerte, el «uno» del compás. La cuenta inicial te da un compás para poner el implemento en movimiento antes de que empiecen los compases contados. Si pierdes el ritmo, no lo persigas: detente, escucha el siguiente «uno» y vuelve a entrar. Los músicos llaman a esto encontrar el inicio del compás, y también funciona para los artistas de flujo.","Contar en voz alta durante unas cuantas sesiones ayuda más de lo que parece. Decir «uno, dos, tres, cuatro» mientras haces malabares ata el ritmo a tu respiración y tu voz, así sobrevive cuando el patrón se complica. Cuando las cuentas vivan en tu cuerpo, desactiva las cuentas habladas en Ajustes y deja que la música te lleve."]},"tempo-ladders":{"title":"Escaleras de tempo: lento es fluido, fluido es rápido","summary":"Sube unos pocos BPM a la vez desde un tempo que puedas hacer limpio, y baja de nuevo en el momento en que la forma se rompa.","imageAlt":"Figura 3D girando un bastón frente al cuerpo en el plano de pared","body":["Una escalera de tempo es el mismo movimiento repetido a tempos crecientes: ocho compases a 80 BPM, ocho a 88, ocho a 96, y así. Es la forma más fiable de hacer un movimiento más rápido sin volverlo más desordenado, y varias rutinas integradas se construyen en torno a ella.","Empieza en un peldaño que puedas hacer limpio, aunque se sienta demasiado fácil. El propósito del peldaño más bajo no es el desafío; es ensayar la forma correcta para que sea la forma lo que se acelere. Sube una cantidad pequeña, alrededor del cinco al diez por ciento. Los saltos grandes cambian el movimiento: los lanzamientos bajan, los giros se vuelven más superficiales y acabas practicando un truco distinto.","Deja de subir cuando se rompa la forma, no cuando dejes caer. Vigila las primeras señales: picos que se vuelven desiguales, el bastón que se sale de su plano, el aro que sube o baja. Esas son las señales para bajar un peldaño y repetirlo. Terminar una escalera con una ronda limpia a un tempo justo por debajo de tu límite le enseña ese tempo a tu cuerpo; terminar con un desastre le enseña el desastre.","Los tempos lentos son más difíciles de lo que parecen para los implementos que giran, porque el implemento tiene menos inercia para atravesarlos. Si un bastón o un aro se estanca en la parte baja de su rango, mantén el tempo y agranda el movimiento ligeramente, o llévalo a mitad de tiempo con la música: un ciclo cada dos pulsos.","Registra tu tempo limpio máximo para cada movimiento en Progreso. Ver ese número subir con las semanas es una buena motivación, y también muestra cuándo un movimiento se ha estancado y necesita un ejercicio diferente en lugar de más de lo mismo."]},"siteswap-notation":{"title":"Siteswap: el malabarismo escrito con números","summary":"Cada número indica cuántos pulsos después se vuelve a lanzar una pelota; los números impares cruzan, los pares se quedan, y el promedio es la cantidad de pelotas.","imageAlt":"Figura 3D haciendo malabares con el siteswap 441 con dos lanzamientos altos y un zip rápido","body":["Los patrones de malabarismo son difíciles de describir con palabras y fáciles de describir con números. El siteswap, desarrollado de forma independiente a mediados de los años ochenta por malabaristas en Cambridge, en Caltech y en Santa Cruz, escribe un patrón como una secuencia repetida de dígitos. Es así como los malabaristas comparten patrones, comprueban si una idea puede funcionar y descubren trucos que nadie ha probado. SynthFlow lo usa para animar cada patrón de malabarismo desde el mismo motor.","Imagina las manos lanzando alternativamente en cada pulso: derecha, izquierda, derecha, izquierda. Cada dígito de un siteswap dice cuántos pulsos desde ahora se volverá a lanzar la pelota lanzada en este pulso. Un 3 vuelve tres pulsos después; como tres es impar, cae en la otra mano. Una cascade de tres pelotas es simplemente 3, 3, 3, 3 para siempre, escrito simplemente como 3. Un 4 vuelve cuatro pulsos después en la misma mano, que es la fountain de cuatro pelotas.","Los números pequeños tienen significados especiales. Un 2 vuelve a la misma mano dos pulsos después, lo que en la práctica significa sostener la pelota un momento. Un 1 cruza a la otra mano en el pulso inmediatamente siguiente, un zip rápido directo al otro lado. Un 0 es una mano vacía. Los números más grandes son lanzamientos más altos: un 5 es un lanzamiento cruzado alto.","Lee un patrón dígito a dígito. En 441, dos lanzamientos se quedan en su propio lado mientras una tercera pelota cruza por debajo de ellos. En 531, un lanzamiento cruzado alto sube mientras un lanzamiento de cascade y un zip mantienen las otras dos pelotas en movimiento. En 423, un lanzamiento a altura de fountain, una pelota sostenida y un lanzamiento de cascade se turnan.","El teorema del promedio te dice cuántas pelotas necesita un patrón: suma los dígitos y divide por cuántos hay. 441 suma 9 entre tres dígitos, así que tres pelotas. Si el promedio no es un número entero, la secuencia no se puede hacer malabares. Una segunda comprobación es que dos pelotas no pueden caer en la misma mano en el mismo pulso, que es como los malabaristas detectan patrones imposibles antes de intentarlos.","El siteswap también tiene notación para ambas manos lanzando juntas, escrita entre paréntesis como (4,4), y para lanzar dos pelotas desde una mano a la vez, escrita entre corchetes. No necesitas nada de esto para hacer buenos malabares, pero una vez que los números encajan, cada nuevo nombre de patrón empieza a explicarse solo. Abre el glosario de Flow para los números individuales."]},"planes-and-geometry":{"title":"Planos: pared, rueda y suelo","summary":"Los implementos que giran viven en planos planos; mantener el plano limpio es la mayor parte de lo que hace que un bastón o un aro se vean nítidos.","imageAlt":"Figura 3D tejiendo un bastón en un ocho en ambos lados del cuerpo","body":["Un bastón o un aro que gira barre una superficie plana, llamada su plano. Los artistas de flujo describen tres planos básicos respecto al cuerpo. El plano de pared está frente a ti, como un cristal contra el que pudieras apoyar las palmas. El plano de rueda está a tu lado, como gira una rueda de carro a lo largo de tu costado. El plano de suelo es horizontal, paralelo al suelo, como en un helicoptero por encima de la cabeza o un lazo.","Los planos limpios son lo que el público lee como habilidad. Un bastón que se tambalea fuera de su plano parece inseguro aunque nunca caiga; un aro que se mantiene perfectamente plano durante un pase parece no costar esfuerzo. La mayor parte de la práctica temprana trata en silencio sobre planos: evitar que las muñecas giren, evitar que los codos se abran y dejar que los hombros muevan el implemento en lugar de las manos.","Muchos trucos se definen por cambiar de plano. Un weave en ocho mueve el bastón del plano de rueda en un lado al plano de rueda en el otro. Un butterfly lo pliega detrás del hombro y lo devuelve. Un escalator camina un aro arriba y abajo del cuerpo mientras su plano se mantiene nivelado. Aprender dónde empieza y termina cada movimiento en el espacio es cómo los enlazas en flow.","El visor 3D puede dibujar el plano mientras practicas. Actívalo cuando aprendas un giro nuevo y compara: ¿tu bastón se inclina hacia ti en la parte superior? ¿el aro baja en la parte delantera? Un espejo o la cámara de un teléfono muestran lo mismo. Mirar desde la vista lateral es especialmente útil para movimientos de plano de pared, porque la inclinación es invisible desde el frente.","Los planos también ayudan con la seguridad y el espacio. Antes de una sesión, comprueba que cada plano que vas a usar esté despejado: la pared frente a ti, las paredes a tus lados y el techo arriba para movimientos de plano de suelo y por encima de la cabeza. Un plano limpio sin nada en él es un plano seguro."]},"spin-and-antispin":{"title":"Spin, antispin e isolations","summary":"Cómo gira el implemento en comparación con la mano da tres familias de movimiento: spin, antispin e isolation.","imageAlt":"Figura 3D dibujando una flor antispin de cuatro pétalos con un staff","body":["Cuando mueves un implemento giratorio en círculo, ocurren dos rotaciones a la vez: tu mano recorre un círculo y el implemento gira sobre su propio centro. La teoría del flow nombra los movimientos según cómo se relacionan esas dos rotaciones. Es el mismo vocabulario para staff, hoop y poi, y por eso las habilidades se transfieren tan bien entre implementos.","En spin, a veces llamado inspin, el implemento gira en el mismo sentido que el círculo de la mano. Es la dirección natural; la mayoría de los primeros giros son inspin sin que nadie los llame así. La forma trazada es una flor cuyos pétalos apuntan hacia afuera.","En antispin el implemento gira en sentido opuesto al círculo de la mano. Al principio se siente raro, como palmear tu cabeza y frotar tu panza a la vez, pero dibuja la clásica flor de pétalos. El número de pétalos depende de cuántas veces gira el implemento por cada círculo de la mano: tres contrarrotaciones por círculo dan cuatro pétalos, que es el Antispin de Cuatro Pétalos en el árbol de staff.","Una isolation es el caso especial en que la mano gira de modo que un punto del implemento parece congelado en el espacio. Con un staff el centro queda quieto mientras los extremos barren a su alrededor; con un hoop el centro del aro o un punto del borde se queda fijo. Las isolations hacen que parezca que el implemento flota y el cuerpo orbita alrededor de él. Exigen trayectorias de mano precisas, lo que las convierte en un entrenamiento excelente para todos los demás trucos.","Aprende estos movimientos despacio y al ritmo. El antispin sobre todo se beneficia de un tempo muy por debajo de tu velocidad normal de giro, con cuentas que nombren dónde debe estar el implemento: arriba, al lado, abajo, al lado. Usa el fantasma del visor 3D para ver la posición del siguiente beat, y la estela para ver si tu flor tiene pétalos parejos.","Cuando spin, antispin e isolation se sientan familiares en un plano, pruébalos en otro. La teoría sigue siendo la misma y tu cuerpo aprende que el plano es solo un ajuste, lo cual es un gran paso hacia improvisar flow."]},"sequencing":{"title":"Cómo se construyen las rutinas de flow","summary":"Calienta, practica un solo enfoque con enlaces que fluyan, mantén pequeños los saltos de tempo y termina con un enfriamiento fácil.","imageAlt":"Figura 3D pasando un hoop de mano en mano frente al cuerpo","body":["Una buena rutina de flow tiene la misma forma que un buen set musical: una apertura que calienta el ambiente, un medio que construye y un final que deja respirar a todos. Las rutinas integradas de SynthFlow siguen esa forma, y el copiloto del constructor revisa la tuya contra ella.","Abre con un calentamiento. Círculos de muñeca, círculos de brazos y rotaciones de hombros llevan las articulaciones que vas a cargar por todo su rango a un tempo suave. Dos o tres minutos alcanzan para una sesión corta; las sesiones más largas y los días fríos merecen más.","Dale al bloque de práctica un solo enfoque. Elige un movimiento en el que estés trabajando y rodéalo de movimientos que enlacen con él. El constructor muestra cómo se conecta cada paso con el anterior: fluir directo desde la misma posición de mano, un pequeño reajuste de agarre, dejar el implemento en el suelo o construir sobre un truco anterior. Las rutinas que fluyen se sienten como bailar; las rutinas llenas de pausas para dejar el implemento se sienten como una lista.","Mantén pequeños los cambios de tempo entre pasos. Saltar de 80 a 130 BPM reinicia tu timing e invita a las caídas. El copiloto marca los saltos de más o menos un cuarto, plegando medio y doble tiempo para que un paso de hoop a 70 BPM pueda convivir con una pista a 140 BPM.","Vuelve al movimiento enfoque más de una vez. La repetición a lo largo de una sesión, con otros movimientos en medio, construye habilidad mejor que un solo bloque largo, porque cada regreso es un intento fresco desde un punto de partida ligeramente distinto.","Termina con un enfriamiento: un movimiento fácil a tempo lento, o un breve descanso con unas cuantas respiraciones. Baja el ritmo cardíaco y le da a tu coordinación un final tranquilo para recordar. Previsualiza la rutina antes de reproducirla y elimina todo lo que sea claramente la ambición de ayer."]},"effort":{"title":"Cuándo subir el tempo","summary":"Sube cuando la forma se mantiene y estás fresco; baja cuando los picos tambalean, el agarre se tensa o las caídas empiezan a agruparse.","imageAlt":"Figura 3D haciendo malabares con cinco pelotas en una cascade alta","body":["El progreso en el flow viene de practicar al borde de tu habilidad, pero el borde se mueve. Algunos días está más lejos de lo que esperas; otros días se ha replegado. Aprender a leerlo es una habilidad que vale tanto como cualquier truco.","Sube cuando lo básico se mantiene. Si tus picos son parejos, tu staff se queda en su plano, tu hoop se mantiene nivelado y tu respiración es fácil, toma el siguiente escalón de la escalera de tempo o prueba el siguiente ejercicio de la progresión. Los primeros quince minutos de una sesión, después del calentamiento, suelen ser el mejor momento para material nuevo.","Baja cuando la calidad se resiente. Las caídas agrupadas, un agarre que se tensa, los hombros que suben hacia las orejas y la respiración contenida dicen que tu sistema nervioso está cansado. Baja el tempo, vuelve a un movimiento que domines o termina la sesión. Empujar a través de la fatiga sobre todo ensaya errores.","Vigila también las señales físicas. Los lanzamientos y giros repetitivos cargan muñecas, antebrazos y hombros. El dolor que se va en un día es adaptación normal. El dolor agudo, el dolor que crece durante la práctica, el entumecimiento o el hormigueo son razones para parar y descansar; los síntomas persistentes merecen un profesional clínico.","Usa la valoración de esfuerzo después de cada sesión. El asistente de práctica la lee: varias sesiones duras seguidas y sugiere algo más suave, varias fáciles y sugiere un poco más. Las valoraciones honestas producen mejores sugerencias."]},"drops-are-data":{"title":"Las caídas son datos","summary":"Una caída te dice qué lanzamiento o recepción arreglar; tratarla como un fracaso solo te enseña a tensarte.","imageAlt":"Figura 3D intercambiando dos pelotas de malabares entre las manos","body":["Todo malabarista tiene el suelo lleno de pelotas en algún momento. Todo spinner de staff ha escuchado el estruendo. La diferencia entre quienes siguen mejorando y quienes lo dejan rara vez es el talento; es cómo tratan la caída.","Una caída es una medición. Te dice qué lanzamiento salió mal, qué recepción estiraste de más, qué momento del giro perdió su plano. Si la misma pelota sigue cayendo delante de ti, tus lanzamientos se están yendo hacia adelante. Si las caídas llegan después de seis lanzamientos, algo en tu tercer o cuarto lanzamiento está fallando. Observa dónde y cuándo, y luego elige una sola cosa para cambiar.","Tratar las caídas como fracaso tiene un costo. El miedo tensa los hombros y acorta la respiración, y la tensión hace los movimientos más pequeños y rápidos, lo que causa más caídas. La respuesta calmada —recoger, respirar, esperar el downbeat, reiniciar— no solo es agradable; es la respuesta técnicamente correcta.","Cuenta las rondas limpias, no las caídas. SynthFlow domina un movimiento cuando tienes suficientes rondas limpias y minutos de práctica, así que las caídas en el camino son simplemente parte de los minutos. Algunos días registrarás diez rondas limpias, otros días dos. Ambos días cuentan.","A veces deja caer a propósito. Cuando aprendas un truco nuevo, practica el primer lanzamiento o el primer medio giro y deja que caiga. Luego añade la recepción. Aislar el momento riesgoso lo encoge, y aprendes que el suelo no es tu enemigo. Es solo donde va el implemento cuando estás aprendiendo."]},"safety":{"title":"Seguridad: espacio, implementos y señales de alerta","summary":"Despeja tus planos, elige implementos indulgentes, calienta y detente ante dolor agudo, entumecimiento o mareo.","imageAlt":"Figura 3D girando un staff plano por encima de la cabeza con espacio libre alrededor","body":["Las artes del flow son de bajo riesgo comparadas con la mayoría de los deportes, pero los implementos se mueven rápido y viajan más lejos de lo que esperas. Unos cuantos hábitos mantienen la práctica segura para ti, para quienes están cerca y para los muebles.","Despeja tu espacio antes de empezar. Revisa cada plano que vas a usar: al frente, a los lados y arriba. El staff y el hoop necesitan más espacio del que crees, normalmente un círculo de al menos tu envergadura más el largo del implemento en cada dirección, sin nada frágil al alcance. En interiores, cuidado con las luces del techo y los ventiladores; al aire libre, cuidado con el suelo irregular y los transeúntes.","Usa implementos indulgentes mientras aprendes. Las pelotas de malabares tipo beanbag no ruedan lejos. Los staffs acolchados o con puntas de espuma duelen menos cuando te golpean la cabeza, cosa que pasará. Un hoop más grande y pesado gira más despacio y es más fácil de mantener arriba. Sube a implementos más rápidos o vistosos cuando lo básico sea automático.","Calienta antes de cada sesión y aumenta el volumen gradualmente. Lanzar y girar son repetitivos, y la carga repetitiva sobre tejido frío es la causa habitual de muñecas y codos doloridos. Si añades mucho volumen de práctica de golpe, añade también días de descanso.","Detente ante señales de alerta: dolor agudo o eléctrico, entumecimiento u hormigueo en las manos, dolor que empeora a medida que continúas, mareo, o un golpe en la cabeza con cualquier síntoma persistente. Los movimientos de cuello y los contact rolls merecen cuidado extra; apréndelos despacio con un implemento acolchado.","Esta app enseña técnica, no es atención médica. Embarazo, lesiones recientes, problemas articulares y cualquier cosa que te preocupe son razones para consultar a un profesional cualificado antes de añadir carga nueva. El fuego es una disciplina aparte con su propia formación en seguridad; SynthFlow no la enseña."]},"warm-up":{"title":"Por qué importa calentar para el trabajo con implementos","summary":"De dos a cinco minutos de movilidad de muñecas, brazos, hombros y caderas hacen los giros más suaves y cuidan tus articulaciones.","imageAlt":"Figura 3D haciendo círculos lentos de muñeca con los brazos al frente","body":["La práctica de flow parece suave, pero exige mucho a unas pocas articulaciones. El malabarismo repite el mismo lanzamiento miles de veces; el staff gira las muñecas por todo su rango; el hoop balancea la columna y las caderas en cada órbita. El tejido caliente tolera esa repetición mucho mejor que el frío.","Un buen calentamiento de flow es corto y específico. Los círculos de muñeca en ambas direcciones preparan las articulaciones que hacen la mayor parte del trabajo. Los círculos de brazos y las rotaciones de hombros despiertan el manguito rotador y los omóplatos, que controlan el plano de cada giro. Los círculos de cadera y los giros de torso importan sobre todo para el hoop. Los semicírculos de cuello, nunca giros completos, alivian la tensión de mirar hacia arriba un patrón.","Muévete despacio y al ritmo. Los pasos de calentamiento en SynthFlow se cuentan como todo lo demás, a un tempo relajado, así que los primeros minutos de una sesión también afinan tu timing. Cuando salen los implementos, ya te estás moviendo con la música.","Termina el calentamiento con el implemento a media velocidad. Unos lanzamientos lentos, un front spin tranquilo o una órbita grande y lenta de hoop conectan el trabajo de movilidad con el movimiento que vas a practicar, y te dicen cómo se siente tu cuerpo hoy.","Los calentamientos también son una transición mental. Los mismos tres minutos al inicio de cada sesión se vuelven una señal de que la práctica ha comenzado. En días ocupados, el calentamiento a veces es toda la práctica, y eso también cuenta."]},"anatomy-basics":{"title":"El cuerpo detrás de los implementos","summary":"Los antebrazos agarran y sueltan, los hombros dirigen el plano, el core te mantiene quieto: un mapa en lenguaje sencillo para el flow.","imageAlt":"Figura 3D haciendo hoop en la cintura con la parte superior del cuerpo relajada","body":["No necesitas saber anatomía para hacer malabarismo, pero un mapa sencillo te ayuda a entender qué se cansa, qué calentar y qué descansar. La sección Músculos de Learn tiene un modelo interactivo; este artículo es el recorrido corto.","Los antebrazos hacen la mayor parte del trabajo fino. Los músculos del lado de la palma cierran los dedos y flexionan la muñeca; los músculos del dorso del antebrazo abren los dedos y extienden la muñeca. Atrapar y soltar, agarrar un staff y dejarlo rodar, todo pasa aquí. La fatiga del antebrazo es la sensación más común tras una sesión larga, y por eso el agarre relajado es una indicación tan frecuente.","Los hombros dirigen. Los deltoides levantan los brazos; el manguito rotador, cuatro músculos pequeños alrededor de la articulación, mantiene centrado el brazo mientras se mueve. Los músculos alrededor de los omóplatos mantienen todo el sistema estable. Cuando un staff se sale de su plano, la causa suele ser el hombro, no la mano.","El core te mantiene quieto. En malabarismo, un torso inmóvil evita que el patrón se desplace. En hoop, los músculos abdominales y de la espalda impulsan el hoop con pequeños pulsos adelante y atrás. Las caderas y las piernas son tu base: rodillas suaves absorben el movimiento y te permiten cambiar el peso sin perturbar el implemento.","Tus ojos y oído interno también importan. El malabarismo te entrena para mirar los picos, no las manos; el giro entrena tu equilibrio. Sesiones cortas con descansos permiten que ambos se adapten sin mareos. Trata este mapa como alfabetización, no como diagnóstico, y consulta a un profesional por dolor que no cede."]},"biomechanics-safety":{"title":"Muñecas, hombros y carga repetitiva","summary":"Agarre relajado, muñecas neutras y volumen gradual mantienen contentas las articulaciones que hacen todo el trabajo.","imageAlt":"Figura 3D girando un staff con una mano sobre el dorso de la mano","body":["Las lesiones en flow rara vez son dramáticas. Casi siempre son por sobreuso: demasiadas repeticiones, demasiado agarre, muy poco descanso. La buena noticia es que los mismos pocos hábitos previenen la mayoría.","Relaja el agarre. Una pelota de malabares solo necesita la presión suficiente para quedarse en la mano; un staff necesita un anillo flojo de dedos dentro del cual pueda rodar. Apretar cansa los músculos del antebrazo y carga los tendones del codo. Si tus nudillos se ponen blancos o los antebrazos arden tras unos minutos, afloja y baja el tempo.","Mantén las muñecas cerca de la neutra cuando puedas. El giro lleva las muñecas por rangos amplios, lo cual está bien con moderación. Mantenerlas al final de su rango por mucho tiempo, o forzar una muñeca rígida a girar, es lo que las irrita. Deja que el codo y el hombro compartan el movimiento.","Deja que los hombros trabajen, pero no se encorven. Los círculos grandes vienen de la articulación del hombro; un hombro encogido pellizca y se cansa rápido. Revisa en el espejo o en el modo cámara que tus hombros se mantengan abajo, sobre todo en movimientos por encima de la cabeza como el helicopter y el lasso.","Aumenta el volumen gradualmente. Si normalmente practicas veinte minutos, no saltes a dos horas porque se acerca un festival. Aumenta el tiempo total una cantidad modesta cada semana y mantén al menos un día fácil. Cambia de implemento para repartir la carga: el trabajo con hoop descansa los antebrazos que cansa el malabarismo.","El dolor que se desvanece en un día es adaptación normal; el dolor que persiste, crece o viene con entumecimiento no lo es. Descansa, reduce el volumen y busca consejo profesional si continúa. Esto es educación, no consejo médico."]},"choosing-props":{"title":"Elegir tus primeros implementos","summary":"Beanbags para malabares, un staff ligero con extremos acolchados y un hoop grande de adulto hacen las primeras semanas mucho más fáciles.","imageAlt":"Figura 3D girando un hoop alrededor de una mano","body":["Buenos implementos de principiante hacen el aprendizaje más rápido y menos frustrante. No necesitas equipo caro, pero algunas elecciones importan.","Para malabares, empieza con tres beanbags de unos 60 a 130 gramos cada uno. Los beanbags no rebotan ni ruedan cuando se caen, lo que ahorra mucho tiempo buscándolos. Deben caber cómodamente en tu palma. Las stage balls, que son más grandes, y las pelotas de silicona con rebote son para después. Colores iguales te ayudan a ver el patrón; tres colores distintos te ayudan a seguir pelotas individuales al aprender siteswaps.","Para staff, un staff de giro de principiante suele medir entre 1,2 y 1,5 metros, ligero, con extremos acolchados o de goma. Como guía aproximada, debe llegar entre tu pecho y tu hombro cuando se apoya en vertical. Un staff más largo y pesado gira más despacio y suave una vez que tienes lo básico, pero es más difícil para empezar y duele más cuando te golpea. Un grip en el medio ayuda.","Para hoop, empieza más grande y pesado de lo que crees. Un hoop de principiante adulto suele llegar entre la cintura y el pecho cuando se apoya en el suelo. Los hoops más grandes rotan más despacio, dándote tiempo para encontrar el ritmo del waist hooping. Los hoops más pequeños y ligeros van bien para trucos rápidos fuera del cuerpo cuando ya estás cómodo.","Elijas lo que elijas, asegúrate de que el rango de tempo del movimiento le vaya bien al implemento. Los implementos más pesados suelen preferir tempos más bajos. Si el rango cómodo de la app se siente apresurado con tu implemento, pon tu propio tempo en el builder; los conteos siguen."]},"practice-at-home":{"title":"Practicar en casa y en el parque","summary":"Sesiones cortas diarias, un espacio despejado, un borde de cama o sofá para atrapar caídas, y una jam en el parque cuando puedas.","imageAlt":"Figura 3D sacudiendo los brazos entre rondas de práctica","body":["La mayoría de los flow artists aprenden en casa, unos minutos a la vez. Un poco de preparación hace que practicar en casa sea más fácil de empezar y de mantener.","Encuentra tu sitio. Para malabares, pararte frente a una cama o un sofá hace que las pelotas caídas aterricen a la altura de la cintura en vez de rodar bajo los muebles, y también evita que camines hacia adelante. Para staff y hoop, busca el espacio despejado más grande que tengas, revisa el techo y aparta lo que sea frágil. Un jardín o parque es mejor para giros grandes.","Mantén los implementos a la vista. Las pelotas sobre el escritorio se usan durante llamadas y pausas de té; un hoop junto a la puerta se usa. Cuanto menos esfuerzo cueste empezar, más a menudo lo harás. Una rutina de cinco minutos cuenta, y varias sesiones cortas al día se suman rápido.","Usa la app como estructura. Elige una rutina o deja que el asistente te sugiera una, practícala completa y registra tu esfuerzo. Programas cortos como Zero to Cascade le dan a cada semana un objetivo claro, lo que evita que te disperses entre trucos.","Practica con otras personas cuando puedas. Existen clubes de malabares, escuelas de circo y quedadas de flow en parques en muchas ciudades. Ver a alguien un paso por delante de ti a menudo corrige algo que un tutorial no pudo, y enseñarle a alguien un paso por detrás de ti hace más clara tu propia técnica. Lleva tus implementos, pregunta en qué están trabajando y comparte lo que los conteos te han enseñado."]},"learning-with-the-app":{"title":"Aprender con el coach 3D","summary":"Bájale la velocidad, refleja el movimiento, activa el fantasma y las estelas, cambia la cámara y usa el modo cámara para recibir feedback.","imageAlt":"Figura 3D realizando una isolation de staff con una estela que muestra la trayectoria","body":["Cada movimiento en SynthFlow está animado en 3D con el mismo reloj que la música, así que la figura siempre está exactamente en el beat. Bien usado, el visor es un maestro paciente que nunca se cansa de mostrarte el mismo lanzamiento.","Primero bájale la velocidad. La escalera de progresión de cada movimiento empieza con versiones lentas y parciales, luego solo manos, y después el movimiento completo en el beat. La media velocidad mantiene intactas las relaciones de tiempo mientras le da tiempo a tus ojos para seguir.","Refleja la figura si aprendes mejor frente a un maestro, y cambia la cámara cuando una vista oculta algo. Las vistas laterales muestran la inclinación del staff y la deriva del lanzamiento; las vistas superiores muestran los planos del hoop y las trayectorias de helicóptero. Las estelas dibujan dónde ha estado cada implemento, lo que convierte un borrón en una forma que puedes estudiar. El fantasma muestra dónde estará el implemento en el siguiente beat.","Observa los errores comunes. Cada movimiento puede mostrar sus fallos típicos, como derivar hacia adelante, alturas desiguales o apurarse, reproducidos deliberadamente mal en la figura, con la señal que los corrige. Reconocer un fallo en el modelo hace mucho más fácil sentirlo en tu propio cuerpo.","El modo cámara te da feedback sobre ti. Con permiso, rastrea tus manos y tu cuerpo mientras practicas y compara tu timing con el beat. El procesamiento ocurre en tu dispositivo. No es perfecto, y una buena luz ayuda, pero incluso un feedback aproximado sobre si vas adelantado o atrasado es valioso.","Por último, cierra el visor de vez en cuando. Practica solo con música y confía en los conteos. El objetivo es un movimiento que puedas hacer sin mirar nada en absoluto."]},"music-for-flow":{"title":"Encontrar música que encaje","summary":"Tempos medidos, mitad y doble tiempo, percusión generada y tus propias pistas mantienen los conteos honestos.","imageAlt":"Figura 3D haciendo hooping al pecho con los brazos levantados","body":["La música convierte la práctica en flow, pero solo si el beat de la música es el beat de los conteos. Una pista a 118 BPM bajo una rutina a 120 BPM se desincroniza en un minuto, y terminas peleando con la música en vez de cabalgarla.","Las pistas incluidas en SynthFlow tienen tempos y downbeats medidos, así que el reproductor puede empezar cada paso en el “uno” de la música y mantener los conteos alineados. El constructor lista primero las pistas que encajan con el tempo de una sección, incluidas pistas a la mitad o al doble del tempo: una pista a 140 BPM lleva perfectamente un paso de hoop a 70 BPM.","La percusión generada funciona a cualquier tempo. Elige un kit para una sección y el reproductor sintetiza un beat que coincide exactamente, ya sea que estés haciendo una escalera de tempo o un drill lento. También es la mejor opción cuando quieres el pulso sin que una melodía te robe la atención.","Puedes analizar pistas desde tu propio dispositivo. La app estima el tempo y el downbeat y te permite verificarlos marcando el ritmo. Las pistas con un pulso electrónico o acústico estable funcionan mejor; la música con cambios de tempo, rubato o intros largas es más difícil de medir y más difícil para practicar.","El streaming de video se desactiva durante la práctica con conteos porque su timing no se puede controlar con precisión. Úsalo para calentamientos o juego libre, donde nada necesita alinearse."]},"plateaus":{"title":"Mesetas y el largo intermedio","summary":"Todo flow artist pasa semanas en las que nada mejora; cambia el drill, el tempo o el implemento antes de cambiar el objetivo.","imageAlt":"Figura 3D haciendo malabares con Mills Mess y los brazos cruzados","body":["El comienzo del flow es maravilloso: algo nuevo cada sesión. Luego, a menudo alrededor del momento en que puedes hacer una cascade estable o mantener un hoop arriba indefinidamente, el progreso parece detenerse. Este largo intermedio es donde la mayoría abandona, y donde ocurre el aprendizaje más interesante.","Las mesetas suelen ser consolidación. Tu sistema nervioso está reorganizando el movimiento para que necesite menos atención, lo cual no se manifiesta como trucos nuevos. A menudo una habilidad que se sintió estancada durante dos semanas aparece de repente una mañana. Sigue practicando durante la parte plana.","Cambia el drill, no el objetivo. Si la cascade no se acelera, practícala a un tempo más bajo con picos perfectos, luego con la mirada en un punto por encima del patrón, luego con una sola mano. Si un movimiento de staff no sale, divídelo en sus mitades y practica cada una al beat. Los drills nuevos le dan a tu cerebro información nueva sobre la misma habilidad.","Entrenamiento cruzado. Aprender un segundo implemento a menudo desbloquea el primero. El hooping mejora el ritmo detrás de los malabares; el trabajo con staff enseña los planos que hacen limpios los trucos de hoop. El árbol de Rewards de cada arte es independiente, así que la variedad nunca cuesta progreso.","Sé amable con esto. Compárate con el mes pasado, no con artistas en línea que han practicado durante diez años. La página de Progress mantiene un registro honesto de minutos, tempos máximos y movimientos dominados. En una semana plana, mírala y observa cuánto ha subido ya la línea."]},"history-of-juggling":{"title":"Una breve historia de los malabares","summary":"Desde una pintura en una tumba egipcia hasta los jongleurs medievales, el teatro de variedades y la matemática moderna.","imageAlt":"Figura 3D haciendo malabares con un shower de tres bolas en círculo","body":["Los malabares son muy antiguos. Una de las imágenes más antiguas que se conocen es una pintura mural en una tumba del Reino Medio en Beni Hasan, Egipto, de unos cuatro mil años de antigüedad, que muestra a mujeres lanzando bolas. Relatos e imágenes de China, Grecia, Roma y el Pacífico sugieren que personas de muchas culturas encontraron su camino hacia lanzar y atrapar para exhibición y juego.","En la Europa medieval, la palabra jongleur, de la que proviene “juggler”, describía a artistas viajeros que cantaban, contaban historias, hacían acrobacias y lanzaban objetos. Los malabares eran una habilidad entre muchas, parte del kit de un artista más que un arte propio.","Los teatros de variedades y circos de los siglos XIX y principios del XX convirtieron los malabares en un acto principal. Los artistas se especializaron: gentleman jugglers con sombreros y bastones, malabaristas de clavas y malabaristas de números empujando hacia siete, ocho y más bolas. Enrico Rastelli, a principios del siglo XX, sigue siendo nombrado a menudo como uno de los más grandes.","A partir de los años 70 creció una cultura de malabares como hobby alrededor de clubes, festivales y convenciones, con personas compartiendo trucos libremente. La matemática se sumó en los años 80 cuando la notación siteswap les dio a los malabaristas una forma de escribir patrones como números, lo que llevó a nuevos trucos descubiertos en papel antes de que alguien los lanzara.","Hoy los malabares se sitúan en el punto de encuentro entre circo, deporte, danza y matemática. Algunos malabaristas compiten en números y resistencia, otros interpretan coreografías con música, otros exploran patrones por sí mismos. Cada ruta empieza con el mismo intercambio de dos bolas, que puedes aprender esta semana."]},"history-of-staff":{"title":"Staff spinning: de arma a flow","summary":"Los bastones de artes marciales, el baton twirling y la performance con fuego alimentaron el moderno spin staff.","imageAlt":"Figura 3D realizando un staff butterfly detrás de los hombros","body":["Un staff es una de las herramientas más antiguas que existen, y hacerlo girar es una habilidad antigua. Muchas tradiciones marciales entrenan con un bastón largo, entre ellas el bō okinawense, el gun chino y el combate con quarterstaff europeo, y sus drills incluyen giros rápidos y cambios de mano tanto para defensa como para exhibición.","El spinning de performance tiene otras raíces también. El baton twirling se convirtió en una disciplina competitiva en el siglo XX, con lanzamientos, rolls y giros que los spinners todavía toman prestados. El teatro, los desfiles y la performance callejera en todo el mundo usaron palos y bastones giratorios mucho antes de que alguien lo llamara flow.","La escena moderna del staff de flow creció a finales del siglo XX junto con la performance con fuego y la cultura de festivales. Los staffs de fuego, con mechas en cada extremo, hicieron visible el giro en la oscuridad y empujaron el arte hacia un movimiento fluido y continuo en lugar de golpes. Los staffs LED trajeron después las mismas visuales al interior.","Casi al mismo tiempo, los flow artists empezaron a describir el giro con una teoría compartida: planos, spin y antispin, isolations, timing y dirección. Mucha de ella se desarrolló en la comunidad del poi y se trasladó al staff, al hoop y a otros props, y por eso las mismas palabras aparecen en toda esta app.","El contact staff, donde el staff rueda sobre el cuerpo en lugar de agarrarse, se convirtió en un estilo propio con rolls por el cuello, los hombros y los brazos. Hoy el staff spinning va desde la demostración marcial hasta el contact flow lento y meditativo, todo construido sobre el mismo primer giro de rueda."]},"history-of-hoop":{"title":"El hoop: de juguete antiguo a flow art","summary":"Los hoops han sido juguetes y herramientas durante milenios; una moda de los años 50 y un renacer en los festivales convirtieron el hoop dance en un arte.","imageAlt":"Figura 3D subiendo un hoop giratorio por el cuerpo","body":["Los hoops están entre los juguetes más antiguos. Se describe o representa a niños del antiguo Egipto, Grecia y Roma haciendo rodar hoops con palos y girándolos alrededor del cuerpo, y los juegos con hoop aparecen en muchas culturas desde entonces.","Los hoops también tienen un profundo significado cultural en algunas tradiciones. El Hoop Dance que se practica en muchas comunidades nativas americanas usa varios hoops para formar figuras como animales y la tierra, contando historias a través del movimiento. Es una tradición viva por derecho propio, distinta de la escena moderna del flow, y vale la pena aprender sobre ella de sus propios practicantes.","La fiebre del hula hoop de plástico de finales de los años 50, impulsada por hoops producidos en masa en Estados Unidos, puso un hoop en millones de hogares casi de la noche a la mañana. Durante décadas después, el hoop se vio sobre todo como un juguete para niños y un aparato de fitness.","Desde finales de los 90 y los 2000, los hoopers adultos en festivales y comunidades online empezaron a tratar el hoop como pareja de baile. Hoops más grandes y pesados hechos a mano facilitaron el hooping on-body para adultos, mientras que los hoops más pequeños abrieron trucos rápidos off-body. Los vídeos compartidos difundieron vocabulario como isolations, wedgies y escalators mucho más allá de una sola ciudad.","El hoop dance moderno toma teoría del staff y del poi, y ritmo de todo tipo de música. Es accesible, alegre y profundo: un principiante puede encontrar el ritmo de cintura en un día, y un experto puede pasar años refinando una sola isolation."]},"fire-and-led":{"title":"Props de fuego, LED y performance","summary":"Los props de performance cambian peso, velocidad y riesgo; aprende cada movimiento primero con props de práctica y entrena el fuego por separado.","imageAlt":"Figura 3D haciendo girar un hoop plano sobre la cabeza como un lazo","body":["Ver un staff de fuego o un hoop LED de noche suele ser lo que atrae a la gente al flow. Los props de performance son maravillosos, pero no son lo mismo que los props de práctica, y pasar a ellos merece un plan.","Los props LED suelen ser más pesados que sus versiones de práctica por las baterías y la electrónica. Eso cambia el momento: los giros llegan más lejos, los lanzamientos se sienten distintos y las muñecas trabajan más. Aprende cada movimiento primero con tu prop de práctica, y luego espera un breve periodo de adaptación con el LED. Baja el tempo en las primeras sesiones.","La performance con fuego es una disciplina aparte. El manejo del combustible, las zonas seguras de giro, los safety spotters con mantas ignífugas, la ropa adecuada y las normas locales importan, y lo mejor es aprenderlo en persona con artistas de fuego con experiencia. SynthFlow no enseña fuego, y nada en la app debe practicarse con props encendidos.","Una buena regla que se usa en muchas comunidades de flow es ejecutar un movimiento con un prop de performance solo cuando puedes hacerlo de forma fiable, muchas veces seguidas, con un prop de práctica. Bajo luces o llamas no hay espacio para experimentos.","La performance también cambia cómo secuencias. El público lee planos grandes, transiciones limpias y momentos claros de quietud. Crea rutinas de performance en el builder como cualquier otra, previsualízalas y ensaya siempre con la misma música para que los counts se vuelvan coreografía."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"El día que la cascade hizo clic","summary":"Tres semanas persiguiendo pelotas por el suelo terminaron en el momento en que dejé de mirarme las manos y empecé a contar.","body":["Durante tres semanas mi cascade de tres pelotas duró exactamente cuatro lanzamientos. Derecha, izquierda, derecha, y luego la tercera pelota estaba en algún lugar detrás del sofá. Vi vídeos, bajé el ritmo, lo subí. Me puse delante de la cama como dicen todos los tutoriales. Nada cambió, excepto mi vocabulario.","La solución, cuando llegó, era vergonzosamente simple. Puse una pista a 90 BPM y dije los counts en voz alta: uno, dos, tres, cuatro, un lanzamiento en cada beat. De repente los lanzamientos tenían un lugar donde estar. En vez de lanzar cuando la mano se sentía lista, lo que significaba cuando el pánico se lo ordenaba, cada lanzamiento esperaba su beat. El patrón se volvió más lento, más alto y más tranquilo.","La segunda solución fue dónde miraba. Había estado mirándome las manos, que es como leer un libro mirándote los párpados. Cuando levanté la mirada hacia los picos, los dos puntos en lo alto de los arcos, mis manos empezaron a atrapar solas. Los picos me decían si los lanzamientos eran parejos; las manos no necesitaban supervisión.","Doce lanzamientos se volvieron veinte, luego cincuenta. Una tarde hice malabares durante todo un paso de ocho compases sin una caída y le sonreí al techo como un idiota. La app lo llamó una clean run. Yo lo llamé la primera vez que los malabares se sintieron como música en vez de una pelea.","Si estás atascado en cuatro lanzamientos, prueba lo que me funcionó: cuenta en voz alta, lanza en el beat, mira los picos. Y suelta sin drama. El suelo es donde empieza toda cascade."]},"why-we-count-in-bars":{"title":"Por qué contamos en compases, no en segundos","summary":"Un aguante de cuarenta segundos tiene sentido para un estiramiento; un patrón de malabares vive en un beat, así que medimos la práctica en compases.","body":["Cuando empezamos a construir SynthFlow, la primera gran decisión fue cómo medir un paso de rutina. Nuestra app hermana SynthYoga cuenta los aguantes en segundos y respiraciones. Eso funciona para una postura que mantienes. No funciona para un patrón que se repite en un beat.","Un lanzamiento de malabares, un medio giro de staff y una órbita de hoop son todos ciclos. Si la música va a 100 BPM y tu cascade va a 103, no estás haciendo malabares con la música; los estás haciendo cerca de ella, y en un minuto vas un beat por detrás. Medir los pasos en compases a un tempo hace que la música, los counts, la figura 3D y el siguiente paso empiecen todos en el mismo downbeat.","Los compases también hacen concreto el progreso. “Haz malabares durante un minuto” es vago: ¿un minuto de qué, a qué velocidad? “Ocho compases de cascade a 96 BPM” es un reto específico y repetible. Si lo consigues limpiamente, la siguiente sesión puede pedir 104. Así funcionan las escaleras de tempo, y por eso la maestría en la app depende de clean runs y no solo del tiempo.","Requiere ingeniería seria. Cada animación está impulsada por el mismo reloj de audio que la música, programada con antelación para que nada se entrecorte. Las pistas incluidas tienen tempos y downbeats medidos. La percusión generada llena cualquier tempo que elijas. Las pistas de tu dispositivo se analizan y se comprueban con una prueba de taps. El vídeo en streaming se desactiva en la práctica contada porque no podemos mantenerlo en el beat.","El resultado es que el beat se convierte en maestro. Cuando te desvías, lo oyes. Cuando te sincronizas, lo sientes. Contar en compases resultó ser la decisión de diseño más importante que tomamos."]},"staff-hit-me-in-the-head":{"title":"El staff me golpeó en la cabeza (y otras lecciones)","summary":"Todo staff spinner recibe golpes; el acolchado, los planos y la paciencia convierten los golpes en progreso.","body":["Mi primer figure-8 terminó con el staff rebotando en mi cráneo y el perro saliendo de la habitación. Mi segundo terminó igual, menos el perro. Si estás aprendiendo staff, te van a golpear. La pregunta es con cuánta fuerza, y qué aprendes de ello.","Lección uno: el acolchado no es cobardía. Un staff de práctica con extremos blandos convirtió los golpes de gritos en encogimientos de hombros. Encogerse importa, porque el miedo te hace flaquear, y una muñeca que flaquea saca el staff de su plano, lo que causa el siguiente golpe.","Lección dos: la mayoría de los golpes vienen de planos inclinados. Cuando me grabé desde el lado, pude ver el staff inclinándose hacia mi cara en lo alto de cada giro. Mis muñecas rodaban hacia dentro. La superposición de planos en el visor 3D mostraba la versión limpia: el staff en una hoja plana al lado del cuerpo, sin inclinarse nunca hacia dentro. Arreglar la muñeca arregló los golpes.","Lección tres: lento y contado vence a rápido y con esperanza. Bajé el tempo al mínimo del rango del figure-8 y conté “lado derecho, lado izquierdo” con la música. A esa velocidad podía sentir el cambio de mano y mantener el plano plano. Una semana después pude volver a subir.","Lección cuatro: ríete. El staff spinning es ridículo y maravilloso. Los golpes son parte de la historia que comparte todo el mundo en la escena. Ponte un gorro si lo necesitas, despeja las luces del techo y sigue girando."]},"hooping-for-people-who-cant-hoop":{"title":"Hula hoop para quienes creen que no pueden hacer hula hoop","summary":"La mayoría de los adultos que “no pueden hacer hula hoop” recibieron un aro del tamaño de un juguete; un aro más grande y un pulso hacia adelante y hacia atrás solucionan casi todo.","body":["“No puedo hacer hula hoop” es algo que los profesores de hoop escuchan constantemente, normalmente de alguien que lo intentó por última vez con un aro de juguete para niños. Los aros pequeños y ligeros giran rápido y caen rápido. Exigen caderas rápidas y frenéticas. Los adultos con un aro de tamaño adulto suelen encontrarlo mucho más manejable.","Empieza grande. Un aro que llega más o menos entre tu cintura y tu pecho cuando lo apoyas en el suelo gira lo bastante despacio para que sientas el ritmo. Los aros más pesados también llevan más impulso. Puedes pasar a uno más pequeño después para velocidad y trucos fuera del cuerpo.","Pulsa, no dibujes círculos. El error más común es intentar hacer círculos grandes con las caderas. El hoop en cintura suele ser un pequeño balanceo hacia adelante y hacia atrás, o de lado a lado, al ritmo del aro. Un pie ligeramente adelantado ayuda. El aro toca tu frente y tu espalda; empujas suavemente cuando pasa.","Cuéntalo. Un tempo relajado, una órbita por beat, le da a tu cuerpo un ritmo en el que asentarse. La app empieza el hoop en cintura lento y luego te deja subir. Si el aro se hunde, añade un poco de velocidad a tu pulso, no un movimiento más grande.","Espera que se caiga mucho durante unas sesiones, y luego, de repente, que no se caiga. El hoop es una de esas habilidades que hacen clic. Cuando lo hace, hay todo un mundo de flow en el cuerpo y fuera de él esperándote, y mucho no necesita ni la cintura."]},"unlocking-is-not-a-race":{"title":"Desbloquear no es una carrera","summary":"El árbol de recompensas abre movimientos más difíciles a medida que dominas sus bases; lo importante son las bases.","body":["Las recompensas de SynthFlow son movimientos. Domina la cascade y se abre la reverse cascade; domina el front spin y aparece el figure-8. Es satisfactorio ver el árbol iluminarse, y lo diseñamos para que lo sea. Pero hay una trampa en cualquier sistema de desbloqueo, y vale la pena nombrarla.","La trampa es tratar el dominio como una casilla que marcar. Técnicamente puedes registrar las rondas limpias de un movimiento en un buen día, desbloquear el siguiente y seguir adelante con una base que solo funciona cuando todo sale bien. Entonces los movimientos más difíciles parecen imposibles, porque asumen que la base funciona cuando las cosas salen mal.","Dominio en el flow significa que el movimiento sobrevive a la distracción: un poco de fatiga, un tempo diferente, alguien que pasa caminando. Por eso el dominio pide rondas limpias a lo largo de varias sesiones, no solo en una. Y por eso sugerimos volver regularmente a los movimientos dominados. La cascade no es un nivel que terminas; es el suelo sobre el que se sostiene todo el árbol del malabarismo.","Los movimientos bloqueados también tienen páginas. Puedes leer sobre ellos, verlos en 3D y ver qué necesitan. Mirar hacia adelante motiva. Practicar hacia adelante, sin las bases, es sobre todo frustrante.","Así que disfruta los desbloqueos, pero mídete por lo fáciles que se sienten tus movimientos más antiguos. Cuando la cascade sea aburrida, estarás listo para Mills Mess. Cuando Mills Mess sea aburrido, el árbol tendrá más que ofrecer."]},"practice-in-ten-minutes":{"title":"Una práctica real en diez minutos","summary":"Calentamiento, un movimiento foco, un enlace, una subida corta de tempo y una vuelta a la calma: diez minutos, cada día.","body":["La razón más común que la gente da para no practicar es el tiempo. La verdad es que las habilidades de flow responden de maravilla a sesiones cortas y frecuentes. Esta es la forma de diez minutos que usamos nosotros mismos.","Minuto uno a dos: calentamiento. Círculos de muñeca, círculos de brazos, rotaciones de hombros, algunos círculos de cadera si haces hoop. Contados, a un tempo relajado, para que tu timing despierte junto con tus articulaciones.","Minuto tres a cinco: tu movimiento foco. Un movimiento en el que estás trabajando, a un tempo que puedas hacer limpio. Varios pasos cortos contados en lugar de uno largo, con una respiración entre ellos.","Minuto seis a siete: un enlace. Empareja el movimiento foco con algo hacia lo que fluya o desde lo que fluya. Cascade a reverse cascade. Front spin a figure-8. Cintura a pecho. Los enlaces son lo que hace que la práctica se sienta como flow en lugar de ejercicios.","Minuto ocho a nueve: una pequeña subida de tempo. Dos o tres peldaños, unos pocos BPM cada uno, parando antes de que se rompa la forma. Termina en un peldaño limpio.","Minuto diez: vuelta a la calma. Un movimiento lento y fácil o un breve descanso. Registra tu esfuerzo. Listo.","Diez minutos al día son más de una hora a la semana de práctica enfocada, repartida de la forma que más le gusta a la coordinación. El asistente de práctica construye sesiones de este tamaño cuando le dices que andas corto de tiempo, y las rutinas cortas integradas siguen la misma forma."]},"antispin-broke-my-brain":{"title":"El antispin me rompió el cerebro (por una semana)","summary":"Girar el staff contra el círculo de la mano parece imposible hasta que los conteos le dan un beat a cada pétalo.","body":["El antispin es donde el staff spinning empieza a sentirse como tarea de geometría. Tu mano dibuja un círculo en una dirección mientras el staff gira en la otra, y los extremos trazan una flor. La primera vez que lo intenté, produje algo más parecido a un diente de león marchito.","Lo que ayudó fue hacer la forma contable. Un antispin de cuatro pétalos tiene cuatro momentos en los que un extremo apunta directamente hacia fuera del círculo. Le di un beat a cada uno: arriba, lado, abajo, lado. Luego bajé la música muy por debajo de mi tempo normal de giro y simplemente apunté a las posiciones en los beats.","El ghost del visor 3D, que muestra dónde debería estar el staff en el siguiente beat, fue mi mejor amigo esa semana. También lo fue el trail, que dibujaba mi flor para que pudiera ver cuándo los pétalos estaban desiguales. Normalmente el pétalo de abajo quedaba aplastado, porque iba con prisa en la parte baja del círculo.","Después de aproximadamente una semana, algo cambió. Dejé de pensar en la mano y el staff como dos cosas y empecé a sentir la flor como una sola forma. El tempo volvió a subir por sí solo.","Si el antispin te está rompiendo el cerebro, se supone que lo haga. Dale un beat a cada pétalo, baja la música y deja que tu cuerpo lo resuelva. Es una de las mejores sensaciones en el flow cuando lo logra."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps para los que le huyen a las matemáticas","summary":"No necesitas que te gusten las matemáticas para usar siteswap; solo necesitas saber que los números más grandes van más alto.","body":["La notación siteswap tiene reputación de asustar a la gente. Los malabaristas dicen alegremente “prueba 531” como si eso explicara algo. Lo hace, pero solo una vez que sabes un par de cosas, y esas cosas son más simples de lo que parecen.","Aquí está casi todo lo que necesitas. Cada número es un lanzamiento. Los números más grandes van más alto. Los números impares cruzan a la otra mano; los pares vuelven a la misma mano. Un 3 es un lanzamiento normal de cascade. Un 1 es un zip rápido de un lado a otro. Un 2 normalmente es solo sostener la pelota.","Eso es suficiente para leer 441: dos lanzamientos más altos que se quedan en su propio lado, luego un zip al otro lado. Ya puedes intentarlo sin leer otra palabra. Lanza, lanza, zip, en el beat.","Si quieres una pieza más: suma los números y divide por cuántos hay, y obtienes el número de pelotas. 4 + 4 + 1 = 9, dividido por 3 son 3 pelotas. Si la respuesta no es un número entero, el patrón no se puede hacer malabares. Eso es todo el famoso teorema del promedio.","En SynthFlow, cada movimiento de malabarismo tiene un siteswap, y el motor 3D se anima directamente a partir de él. Eso significa que la figura siempre lanza exactamente las alturas que describen los números, en los beats exactos. Ver un siteswap animado lentamente es la forma más rápida que conocemos de hacer que los números tengan sentido. No se requiere título en matemáticas."]},"music-that-fights-you":{"title":"Cuando la música te pelea","summary":"Una pista que se desvía contra los conteos hace que cada movimiento sea más difícil; los tempos medidos y los beats generados lo arreglan.","body":["Probablemente lo has sentido: una canción que amas, un movimiento que conoces y, de alguna manera, todo se siente mal. Te apuras, se te cae, te culpas. A menudo el problema no eres tú. Es que el tempo de la canción no coincide con el movimiento.","Cada movimiento de flow tiene un rango de tempo cómodo. Por debajo, los props se estancan; por encima, los lanzamientos salen bajos y frenéticos. Una pista a 128 BPM bajo un movimiento de hoop que prefiere 90 te obliga a elegir entre la música y el hoop. La buena noticia es que half time y double time ayudan: 128 puede llevar un movimiento a 64, un ciclo cada dos beats.","El drift es el problema más sutil. Si la música dice 120 pero los counts dicen 116, los dos se separan con el tiempo, y tu cuerpo no puede seguir a ambos. Por eso SynthFlow usa tempos medidos para sus pistas incluidas, genera percusión a cualquier tempo exacto y verifica las pistas de tu dispositivo con un tap test.","Cuando una pista te pelea, no le devuelvas el golpe. Cambia al beat generado para el paso, o deja que el builder te sugiera una pista en el rango correcto. Guarda las canciones que amas para el free play, donde nada necesita cuadrar.","La música debe sentirse como una compañera. Si se siente como una oponente, cambia la música, no tu movimiento."]},"learning-alongside-my-kid":{"title":"Aprender a hacer malabares junto a mi hijo","summary":"Dos principiantes, una bolsa de pelotas y una regla: celebramos las caídas tan fuerte como las atrapadas.","body":["Mi hija pidió aprender malabares, y me di cuenta de que yo tampoco sabía. Así que aprendimos juntos, diez minutos después de cenar, con tres beanbags cada uno y una regla: celebramos las caídas tan fuerte como las atrapadas.","La regla suena tonta. Resultó ser la parte más importante. Los niños, y los adultos, se tensan cuando creen que un error es vergonzoso. La tensión empeora los lanzamientos. Celebrar cada caída convirtió el suelo en parte del juego y nos mantuvo sueltos a los dos.","Empezamos con una pelota, lanzándola de mano en mano al beat, con picos a la altura de los ojos. Se sintió demasiado fácil durante unas tres sesiones y luego, de repente, importante, porque los intercambios con dos pelotas solo funcionan si esos lanzamientos individuales son consistentes. Ella dominó el intercambio antes que yo y fue insoportable al respecto.","La música con counts nos ayudó a practicar juntos. Mismo tempo, mismo downbeat, dos personas lanzando a tiempo. Cuando uno perdía el patrón, el otro seguía, y el que había soltado volvía a entrar en el siguiente “one”.","A las cuatro semanas, los dos tenemos una cascade tambaleante. Más importante aún, tenemos un hábito que ambos esperamos con ganas. Si tienes un hijo que quiere aprender algo, apréndelo con él. Ser principiantes juntos está infravalorado."]},"why-your-throws-drift-forward":{"title":"Por qué tus lanzamientos se van hacia adelante","summary":"Si terminas cada cascade a tres pasos de donde empezaste, tus lanzamientos se están inclinando lejos de ti. Aquí te contamos cómo traerlos de vuelta.","body":["Todo malabarista conoce el caminar. Empiezas la cascade en el centro de la sala y la terminas con la nariz contra la pared, persiguiendo el patrón paso a paso. Se siente como si las pelotas te tiraran. No lo hacen. Las estás lanzando hacia adelante, unos centímetros a la vez, y luego caminas para alcanzarlas.","La causa casi siempre son los codos. Cuando te pones tenso, los antebrazos se inclinan hacia adelante y las manos sueltan la pelota un poco delante del cuerpo. Cada lanzamiento cae un poco más lejos, así que la siguiente recepción ocurre más lejos, así que el siguiente lanzamiento empieza más lejos. Se acumula rápido.","La solución que enseño primero es pegar los codos. Mantén los codos cerca de las costillas, los antebrazos más o menos nivelados, y lanza las pelotas rectas hacia arriba, pasando por delante de tus ojos, en lugar de hacia adelante. Se siente apretado por un día. Después se siente tranquilo.","La segunda solución es una pared. Párate frente a ella, a un antebrazo de distancia, y haz malabares. Si los lanzamientos se desvían, la pared te lo dice de inmediato, y fuerte. Diez minutos de práctica contra la pared le enseñan al cuerpo cómo se siente un patrón vertical más rápido que cualquier cosa que yo pueda decir.","El modo cámara de SynthFlow también detecta la deriva. Rastrea cuánto más grande se ve tu torso ante la cámara con cada paso, lo que significa que estás caminando hacia ella, y te avisa con una señal corta. El coach 3D también puede mostrar el fantasma de un lanzamiento hacia adelante junto al limpio, para que veas la diferencia en lugar de solo escucharla.","La deriva no es un defecto de carácter. Es un hábito de tensión, y los hábitos cambian con la repetición. Pega los codos, lanza hacia arriba y no hacia afuera, y deja que la pared te mantenga honesto."]},"practising-to-a-click":{"title":"Practicar con un click","summary":"Un metrónomo suena como lo menos divertido del mundo. Resultó ser lo que hizo que mi flow se sintiera como bailar.","body":["Resistí el click durante años. La música era el sentido del flow arts para mí, y un metrónomo se sentía como tarea. Entonces una amiga que toca batería me vio hacer malabares y me dijo, con cariño, que aceleraba cada vez que me emocionaba y frenaba cada vez que me asustaba. Tenía razón, y yo no tenía idea.","Así que probé una semana de práctica con nada más que un clic. El primer descubrimiento fue que un pulso constante es más difícil de lo que suena. Mi patrón de dos en una mano quería acelerarse. Mi figura-8 con el staff quería arrastrarse en el lado débil. Al clic no le importaba cómo me sentía; solo mantenía el tiempo.","El segundo descubrimiento fue que el clic hacía la música más fácil. Después de una semana, cuando volví a poner pistas reales, podía sentir dónde se asentaba el beat dentro del sonido. Dejé de pelear con canciones de timing suelto y empecé a elegir en qué parte del groove engancharme.","La percusión generada de SynthFlow es una versión más amigable del clic. Eliges un kit, desde un clic simple hasta tambores de mano, y toca a cualquier tempo, así un patrón puede vivir exactamente a la velocidad que puedes sostener. También puede sonar bajito bajo una pista de música como guía. Yo todavía lo uso solo durante los primeros minutos de cada sesión.","Si quieres probar esto, elige un patrón y un tempo que se sienta un poco demasiado lento. Cuenta en voz alta durante cuatro compases, luego deja de contar y solo escucha. Cuando el patrón y el clic se sientan como un solo sonido, sube cuatro BPM. Ese es todo el método."]},"staff-in-a-small-apartment":{"title":"Staff en un apartamento pequeño","summary":"Un staff de 1,4 metros y un techo de 2,4 metros pueden convivir. Solo tienes que elegir tus planos.","body":["Mi piso tiene techos bajos, una lámpara a la que le tengo cariño y un vecino de abajo que trabaja de noche. Nada de eso es ideal para girar el staff. Practiqué en parques durante un año antes de darme cuenta de que la mayor parte de mi entrenamiento podía ocurrir bajo techo después de todo.","El truco son los planos. Los giros en plano de rueda, los grandes al lado del cuerpo, necesitan toda la altura del staff por encima de tu cabeza. El trabajo en plano de pared frente al cuerpo necesita anchura pero menos altura. Los giros en plano de suelo, como el helicóptero, necesitan espacio libre sobre tu cabeza pero nada alrededor de tus espinillas. Cada habitación soporta movimientos diferentes.","En mi sala puedo hacer isolations, giros frontales y figura-8s lentos con los brazos bajos. En el pasillo no puedo hacer nada en absoluto, así que el pasillo es para calentamientos de muñeca. El dormitorio tiene el techo más alto, así que el trabajo en plano de rueda ocurre ahí, despacio, con la lámpara quitada y guardada en un cajón.","Los staffs cortos también ayudan. Un staff de práctica una mano más corto que mi staff de presentación convirtió muchos casi-choques en espacio libre fácil. El timing cambia un poco, así que reviso mi staff de longitud completa afuera una vez por semana.","Para los vecinos: mats de práctica y staffs con puntas suaves. Una caída sobre un mat de yoga es un golpe sordo en vez de un estallido. También mantengo las sesiones bajo techo en rutinas contadas de diez minutos, lo que mantiene el ruido corto y la práctica enfocada.","SynthFlow te deja marcar movimientos que no puedes hacer en casa como no deseados para que el generador los deje fuera de las rutinas de interior. Los espacios pequeños no detienen el progreso. Solo te hacen muy bueno en isolations."]},"hooping-after-40":{"title":"Hooping después de los 40","summary":"Tomé un hoop por primera vez a los 43. Mi espalda, mis rodillas y mi orgullo tenían opiniones. Esto es lo que funcionó.","body":["Compré mi primer hoop de adulto por capricho después de un festival, convencido de que sería terrible. Fui terrible. También, en un mes, estaba haciendo hooping en la cintura durante canciones enteras, y en seis meses haciendo movimientos simples fuera del cuerpo. La edad no me detuvo. Solo cambió cómo necesitaba practicar.","La gran lección fue calentar bien. Círculos de cadera, giros de torso y rebotes suaves de rodilla toman tres minutos y hacen que el primer hoop de la sesión se sienta fluido en vez de crujiente. SynthFlow pone calentamientos al inicio de cada rutina por una razón, y dejé de saltármelos después de una mañana rígida.","La segunda lección fue el tamaño del hoop. Un hoop más grande y un poco más pesado gira más despacio, lo que te da más tiempo y le pide menos esfuerzo a la espalda baja. Empecé con un hoop que llegaba entre mi cintura y mi pecho cuando estaba de pie en el suelo, y todavía lo uso para sesiones largas de práctica.","Tercero: pulsa, no circules. Los principiantes a menudo balancean las caderas en un círculo, lo que tuerce la columna más de lo necesario. Un pulso de adelante hacia atrás, o de lado a lado si el hoop gira así para ti, mantiene el hoop arriba con menos tensión. El coach 3D muestra esto claramente si miras las caderas en vez del hoop.","Finalmente, corto y frecuente vence a largo y ocasional. Diez minutos cuatro veces por semana hicieron más por mí que una hora el domingo. Mi cuerpo se recuperaba entre sesiones, y los movimientos se quedaban.","Si tienes más de 40 y curiosidad, empieza. El hoop no sabe cuántos años tienes."]},"fire-and-the-beginner":{"title":"Fuego y el principiante","summary":"El fire spinning es la parte más visible de las flow arts y la parte por la que más preguntan los principiantes. La respuesta honesta es: todavía no, y no solo.","body":["Cada semana alguien nos pregunta cuándo SynthFlow enseñará fuego. Es una pregunta justa. El fuego es hermoso, y muchos spinners entraron a la escena después de ver un círculo de fuego de noche. Pero nunca vamos a entrenar a nadie para encender un prop, y este post explica por qué.","El fuego añade peligros que no tienen nada que ver con la habilidad: manejo de combustible, ropa, viento, espectadores, quemaduras y extinción. Estas cosas se aprenden de personas experimentadas en persona, con una persona de seguridad entrenada presente y equipo adecuado listo. Una app no puede revisar tu depósito de combustible, tu ropa de algodón o tu toalla de seguridad.","Lo que la app sí puede hacer es ayudarte a construir las habilidades que el fuego necesita antes de que te acerques a él. Eso significa movimientos que puedes hacer de forma confiable durante una canción entera, a un tempo constante, sin caídas. Si un patrón todavía te sorprende en casa con un prop de práctica, no está listo para fuego.","Una prueba útil de la comunidad de fuego: ¿puedes hacer la rutina con los ojos medio cerrados, en la oscuridad, mientras alguien te habla? El fuego es brillante, caliente y ruidoso, y toma tu atención. Tu cuerpo tiene que saber los movimientos sin supervisión.","Los props LED son un gran paso intermedio. Te dan el look nocturno, las estelas y la reacción del público sin el riesgo. El pack de estilo LED de SynthFlow muestra cómo se verán tus patrones iluminados, lo que también es una buena forma de detectar planos descuidados.","Cuando estés listo, encuentra un fire jam local, preséntate y pide aprender seguridad primero. Gira props de práctica hasta entonces. El fuego seguirá ahí."]},"four-balls-taught-me-patience":{"title":"Cuatro pelotas me enseñaron paciencia","summary":"Pasar de tres pelotas a cuatro me tomó más tiempo que aprender tres desde cero, y cambió cómo pienso sobre la práctica.","body":["Tres pelotas me tomaron cinco semanas. Cuatro me tomaron cinco meses. Nadie me advirtió sobre esto, así que te advierto: cuatro pelotas no es tres pelotas más una. Es un patrón completamente diferente, y tu cuerpo tiene que aprenderlo desde cero.","En una fuente de cuatro pelotas, cada mano hace malabares con dos pelotas por su cuenta, y las pelotas nunca se cruzan. Las manos normalmente alternan, pero no hay intercambio entre ellas en absoluto. Todo lo que había aprendido sobre atrapar una pelota de la otra mano de repente era inútil.","Así que volví a una mano. Dos pelotas en la mano derecha, en columnas, luego círculos, hasta que podía hacer cincuenta lanzamientos sin pensar. Luego la mano izquierda, que tomó tres veces más. Luego ambas manos juntas, primero en sincronía, luego alternando. La escalera de tempo en SynthFlow ayudó aquí: empezaba cada semana en el fondo del rango de la fuente y solo subía después de una ronda limpia.","La lección de paciencia vino de los estancamientos. Algunas semanas nada mejoraba. Grabé caídas y rondas limpias de todos modos, y el gráfico mostraba progreso lento incluso cuando se sentía como nada. Los datos hicieron las semanas aburridas soportables.","La otra lección fue sobre el descanso. Cuatro pelotas cansaban mis antebrazos de una forma que tres nunca lo hicieron. Cuando practicaba todos los días, empeoraba. Cuando practicaba día por medio, mejoraba. Los músculos de agarre necesitan recuperación como cualquier otro.","Si estás atascado entre tres y cuatro, divide el problema, confía en las semanas lentas y dale un día libre a tus antebrazos. Llega."]},"the-escalator-and-hand-traffic":{"title":"La escalera y el arte del tráfico de manos","summary":"Los movimientos de manos con hoop parecen magia hasta que ves que son solo una gestión cuidadosa del tráfico entre dos manos.","body":["La primera vez que vi una escalera, el hoop parecía subir por los brazos del hooper y flotar hacia abajo de nuevo, sin fin, sin un agarre obvio. Asumí que necesitaba años de práctica. Necesitó unas tres semanas, una vez que entendí que es solo un patrón de traspasos.","Casi todo movimiento de hoop fuera del cuerpo se trata de qué mano sostiene el hoop, cuándo lo suelta y dónde lo encuentra la otra mano. Si el timing entre las manos es difuso, el hoop se tambalea fuera de su plano y el movimiento se desmorona. Si el timing es limpio, el hoop parece moverse por sí solo.","Así que empecé a nombrar los traspasos. Sobre el conteo de SynthFlow decía las manos en voz alta en lugar de los números: derecha, izquierda, derecha, izquierda, una en cada beat. Decirlas con la música me obligaba a notar cuándo mi mano izquierda agarraba antes de tiempo. Los agarres anticipados eran la fuente de casi todos los tambaleos.","La segunda clave era mantener el hoop en su plano. Una mano que gira al agarrar inclina el hoop, y un hoop inclinado es un hoop que se cae medio segundo después. La superposición de plano ayuda aquí, y también practicar frente a un espejo con tempos lentos.","Una vez que la escalera se sintió confiable, otros movimientos de manos llegaron más rápido. Isolations, pases y lassos usan la misma idea: traspasos claros, planos planos, timing constante. La magia es solo gestión de tráfico."]},"behind-the-back-without-fear":{"title":"Detrás de la espalda sin miedo","summary":"Los pases de staff por detrás de la espalda son donde la mayoría de los spinners se estancan. El problema normalmente no es la habilidad sino las ganas de mirar.","body":["Durante meses mi pase por detrás de la espalda fue un pase frontal con un giro esperanzado. Empezaba el movimiento, entraba en pánico cuando el staff salía de mi vista, y lo traía de vuelta al frente. El staff nunca llegaba realmente detrás de mi espalda. Mi cerebro no lo permitía.","El avance vino de aceptar que no podía ver el movimiento. No puedes mirar un pase por detrás de la espalda. Tienes que sentir dónde está el staff desde la mano que suelta y confiar en la mano que espera.","Entrené esa sensación en cámara lenta. Sin girar en absoluto, pasaba el staff detrás de mi espalda, de mano a mano, con los ojos al frente. Luego con un medio giro lento primero. Luego en el rango más bajo del tempo del movimiento, contado. Cada paso se sentía ridículo. Cada paso funcionó.","El coach 3D fue sorprendentemente útil porque podía rotar la vista y ver el movimiento desde atrás. Ver dónde se encuentran las manos, y cómo el staff se mantiene en el plano de pared mientras da la vuelta, le dio a mi cuerpo un mapa que no podía obtener desde el frente.","El segundo miedo era golpearme. Un staff de práctica con puntas blandas y un espacio amplio y despejado lo resolvieron. Una vez que supe que un error costaría un golpe suave en lugar de un moretón, dejé de encogerme, y el encogimiento había estado causando los fallos.","Si detrás de la espalda todavía te da miedo, bájale la velocidad, quita el giro, y mantén los ojos al frente. Tus manos saben más de lo que crees."]},"why-reverse-feels-wrong":{"title":"Por qué la cascade inversa se siente mal","summary":"La cascade inversa usa las mismas manos, las mismas pelotas y el mismo ritmo que la cascade. Entonces, ¿por qué se siente como empezar de nuevo?","body":["Cuando aprendí la cascade inversa, esperaba que me tomara una tarde. Son las mismas tres pelotas, las mismas manos alternadas y el mismo tempo que la cascade. Me tomó tres semanas, y no podía entender por qué.","La respuesta es la dirección. En una cascade normal, cada pelota se lanza desde el interior del patrón y se atrapa por fuera. En una cascade inversa, la pelota se lanza desde fuera, por encima de la pelota que llega, y se atrapa por dentro. Tus manos hacen el mismo ritmo pero formas completamente diferentes.","La nueva forma rompe tu timing. En la cascade, lanzas justo cuando la pelota que llega empieza a caer. En la inversa, necesitas lanzar un poco antes para que tu pelota pase por encima de la otra. Lanza en el momento antiguo y las pelotas chocan.","Lo arreglé con dos pelotas primero. Dos pelotas, dirección inversa, contado en el beat, hasta que se sintió automático. Luego tres pelotas a tempo lento con los conteos dichos en voz alta. La superposición fantasma de SynthFlow me mostró un error típico, un lanzamiento demasiado bajo que roza la otra pelota, y pude ver que estaba haciendo exactamente eso.","Una vez que hizo clic, desbloqueó mucho. Mezclar cascade e inversa es la base de muchos trucos, y la forma inversa vuelve a aparecer en Mills Mess. Haber sido malo en eso durante tres semanas valió la pena."]},"making-a-prop-stand-still":{"title":"Isolations: hacer que un prop se quede quieto","summary":"Una isolation es un movimiento donde el prop parece quedarse en un solo lugar mientras tú te mueves alrededor de él. Es la ilusión más satisfactoria en las artes de flow.","body":["La primera vez que logré una isolation de staff, mi amigo preguntó cómo flotaba el staff. No flotaba, por supuesto. Mis manos se movían en un círculo cuidadoso para que un punto del staff se mantuviera fijo en el aire. Pero desde fuera parecía imposible, y esa sensación es por lo que amo las isolations.","Toda isolation funciona igual. Elige un punto en el prop, normalmente el centro o un extremo, y mantén ese punto quieto mientras el resto del prop gira. Tus manos tienen que moverse exactamente en la dirección opuesta a como el prop quiere moverse. Es contraintuitivo y ligeramente hipnótico.","La parte más difícil es que tu cuerpo también se mueve. Las caderas se desplazan, los hombros giran, y cada pequeño movimiento aparece como tambaleo en el punto fijo. Practiqué frente a un espejo con un pedazo de cinta en el vidrio marcando dónde debería estar el punto fijo. Si el centro del prop dejaba la cinta, lo sabía.","Las isolations de hoop siguen la misma idea. En SynthFlow activo los trails en el visor 3D y observo al coach: en una isolation limpia, el trail alrededor del punto fijo se mantiene diminuto. Cuando bajé mucho el tempo y lo copié, pude sentir mis manos desviándose en la parte superior de cada círculo.","Las isolations también construyen control que ayuda a todo lo demás. Una vez que puedes mantener un prop quieto, puedes colocarlo donde quieras. Los planos se vuelven más planos, las transiciones más limpias, y tu flow empieza a verse intencional en lugar de afortunado.","Empieza lento, marca el punto fijo, y obsérvalo como un halcón. Luego muéstraselo a un amigo y disfruta su cara."]}}`),i={"zero-to-cascade":{name:`De cero a cascade en 4 semanas`,description:`Una pelota, luego dos, luego se suma la tercera. Una sesión corta al día es suficiente: completa la rutina de cada semana para dominar su movimiento y abrir la siguiente.`,weeks:[{label:`Semana 1 · Una pelota`},{label:`Semana 2 · Dos pelotas`},{label:`Semana 3 · La tercera pelota`},{label:`Semana 4 · Cascade`}]},"staff-foundations":{name:`Fundamentos de staff`,description:`Wheel y front spins, el figure 8 y el pass-through: los cuatro movimientos sobre los que se construye casi todo el staff flow.`,weeks:[{label:`Semana 1 · Wheel spin`},{label:`Semana 2 · Front spin`},{label:`Semana 3 · Figure 8`},{label:`Semana 4 · Pass-through`}]},"off-body-hoop":{name:`Hoop off-body`,description:`Desde girar el hoop en una mano hasta lassos, passes, wedgies y la isolation que hace que el hoop parezca flotar.`,weeks:[{label:`Semana 1 · Hand spin`},{label:`Semana 2 · Lasso y pass`},{label:`Semana 3 · Wedgie`},{label:`Semana 4 · Isolation`}]}},a={"sf-ambient-70":{name:`Órbita lenta`},"sf-world-75":{name:`Pasos de mercado`},"sf-ambient-80":{name:`Deriva de farol`},"sf-world-85":{name:`Rueda del desierto`},"sf-handdrum-90":{name:`Tambor circular`},"sf-funk-95":{name:`Muñecas sueltas`},"sf-handdrum-100":{name:`Manos de fuego`},"sf-world-105":{name:`Campanas de río`},"sf-funk-110":{name:`Cascada de bolsillo`},"sf-handdrum-115":{name:`Groove de patio`},"sf-electronic-120":{name:`Staff de neón`},"sf-funk-125":{name:`Patrón de Rebote`},"sf-electronic-130":{name:`Hula Hoop Pixel`},"sf-handdrum-135":{name:`Djembe del Atardecer`},"sf-electronic-140":{name:`Estelas LED`},"sf-funk-145":{name:`Ciclo de Giro`},"sf-electronic-150":{name:`Flow Estroboscópico`},"sf-handdrum-155":{name:`Palmas Rápidas`},"sf-electronic-160":{name:`Girante Nocturno`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};